#include <stdio.h>
#include <string.h>
void order(char *items[], int count);
int main(void) {
    char original[3][8] = {"pear","elm","oak"};
    char *view[3] = {original[0],original[1],original[2]};
    order(view, 3);
    for (int i = 0; i < 3; i++) puts(view[i]);
    puts("ORIGINAL");
    for (int i = 0; i < 3; i++) puts(original[i]);
    return 0;
}
void order(char *items[], int count) {
    for (int top = 0; top < count - 1; top++) {
        for (int seek = top + 1; seek < count; seek++) {
            if (strcmp(items[top], items[seek]) > 0) {
                char *saved = items[top];
                items[top] = items[seek];
                items[seek] = saved;
            }
        }
    }
}

