#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
void inspect(const char *text, int base);
int main(void) {
    char line[24];
    while (fgets(line, sizeof line, stdin) != NULL) {
        char *newline = strchr(line, '\n');
        if (newline != NULL) *newline = '\0';
        if (line[0] == '\0') break;
        inspect(line, 10);
        inspect(line, 16);
    }
    return 0;
}
void inspect(const char *text, int base) {
    char *end;
    errno = 0;
    long value = strtol(text, &end, base);
    if (end == text || errno == ERANGE) puts("INVALID");
    else printf("base%d=%ld rest=%s\n", base, value, end);
}

